<script setup lang="ts">
import { destinations, itineraries } from '~/data/itineraries'
const route = useRoute()
const destination = computed(() => destinations.find(item => item.slug === route.params.slug && item.published))
if (!destination.value) throw createError({ statusCode: 404, statusMessage: 'Destination not found' })
const related = computed(() => itineraries.filter(item => item.status === 'published' && item.destination.locations.some(stop => stop.toLowerCase() === destination.value!.name.toLowerCase())).slice(0, 3))
const { openEnquiry } = useEnquiry()
useSeoMeta({ title: () => `${destination.value?.name ?? 'Kerala'} travel planning`, description: () => destination.value?.summary ?? '' })
</script>

<template><div v-if="destination"><section class="inner-hero inner-hero--image" :style="{ backgroundImage: `url(/images/${destination.image})` }"><div class="page-shell inner-hero__content"><span class="hero-chip">{{ destination.region }} · {{ destination.idealNights }}</span><h1>{{ destination.name }}</h1><p>{{ destination.summary }}</p></div></section><section class="section page-shell destination-detail"><div><span class="eyebrow">Plan the stop</span><h2>How {{ destination.name }} works in a Kerala journey.</h2><p>{{ destination.summary }} This is an editable destination template: enrich it with your own on-the-ground experience, hotel recommendations and seasonal advice as Tripport evolves.</p><div class="detail-facts"><div><span>Best for</span><b>Scenic Kerala experiences</b></div><div><span>Ideal stay</span><b>{{ destination.idealNights }}</b></div><div><span>Combine with</span><b>Nearby Kerala highlights</b></div></div></div><aside><span class="eyebrow">Plan a journey</span><h3>Include {{ destination.name }} in your Kerala route.</h3><button class="button button--dark" @click="openEnquiry(`${destination.name} itinerary`) ">Start an enquiry</button></aside></section><section v-if="related.length" class="section section--soft"><div class="page-shell"><div class="section-heading"><div><span class="eyebrow">Suggested routes</span><h2>Itineraries including {{ destination.name }}</h2></div></div><div class="itinerary-grid"><ItineraryCard v-for="item in related" :key="item.slug" :itinerary="item" /></div></div></section></div></template>

<style scoped>.destination-detail{display:grid;grid-template-columns:1fr 350px;gap:80px}.destination-detail h2{max-width:730px;margin:12px 0 16px;font-size:clamp(38px,4vw,62px);line-height:1.02;letter-spacing:-.055em}.destination-detail p{max-width:760px;color:#666;font-size:17px;line-height:1.7}.detail-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:34px}.detail-facts>div{padding:18px;border:1px solid #e4e4e4;border-radius:14px}.detail-facts span{display:block;color:#777;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.detail-facts b{display:block;margin-top:7px;font-size:16px}.destination-detail aside{align-self:start;padding:25px;border-radius:18px;background:#f3f5f3}.destination-detail aside h3{margin:12px 0 20px;font-size:28px;line-height:1.05;letter-spacing:-.04em}.destination-detail aside .button{width:100%}@media(max-width:850px){.destination-detail{grid-template-columns:1fr;gap:36px}.detail-facts{grid-template-columns:1fr}}</style>
